```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

const SYSTEM: &str = "You answer customer support questions using the provided knowledge. \
You may request the `lookup` tool with a search query when you need more knowledge.";

/// Bounded tool-orchestration loop: at most this many tool calls per run.
const MAX_TOOL_ROUNDS: usize = 3;

struct Node;

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn build_prompt(ctx: &ConversationContext, tool_results: &[String]) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(&format!("{:?}", ctx.intent));
    prompt.push_str("\n\nQuestion: ");
    prompt.push_str(&ctx.question);
    prompt.push_str("\n\nKnowledge:\n");
    for k in &ctx.knowledge {
        prompt.push_str("- ");
        prompt.push_str(k);
        prompt.push('\n');
    }
    for r in tool_results {
        prompt.push_str("\nTool result:\n");
        prompt.push_str(r);
        prompt.push('\n');
    }
    prompt
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut tool_results: Vec<String> = Vec::new();
        let mut rounds: usize = 0;

        loop {
            let prompt = build_prompt(&ctx, &tool_results);

            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return fail("requested tool is not in scope");
                    }
                    if rounds >= MAX_TOOL_ROUNDS {
                        return fail("tool call budget exhausted");
                    }
                    rounds += 1;

                    let hits = kb_read::lookup(&req.query);
                    tool_results.push(format!(
                        "lookup({}) -> {}",
                        req.query,
                        hits.join("\n")
                    ));
                }
            }
        }
    }
}

export!(Node);
```

